package org.rabochaya.maptests;
import android.app.*;import android.content.*;import android.view.*;import java.util.*;import org.json.*;
/** Measured baseline only: dirty editor close intent across actual destruction. */
final class GeometryCloseConfirmationChecks {
 final MapAndroidChecks m;final MapVertexConfirmationChecks c;final GeometryConfirmationChecks g;final ManagerVisualChecks v;final ManagerRotationChecks r;
 GeometryCloseConfirmationChecks(MapAndroidChecks m){this.m=m;c=new MapVertexConfirmationChecks(m);g=c.g;v=c.v;r=c.r;}
 boolean present(){return g.contains(m.activeDialogRoot(),"Сохранить ввод как локальный черновик и закрыть редактор?")&&v.button(m.activeDialogRoot(),"Сохранить черновик")!=null&&v.button(m.activeDialogRoot(),"Продолжить редактирование")!=null&&v.button(m.activeDialogRoot(),"Отменить ввод")!=null;}
 void prompt()throws Exception{m.click("Закрыть");m.check(present(),"explicit Close opens dirty editor confirmation");}
 void snapshot(String tag)throws Exception{JSONObject o=new JSONObject();o.put("stage",tag);o.put("present",present());o.put("layout",c.layout());o.put("project",m.editorField("project"));o.put("feature",m.editorField("featureId"));o.put("process",m.editorField("VERTEX_SESSION"));o.put("key",g.key());o.put("token",m.editorField("expected"));o.put("raw",m.editorText());Object s=m.editorField("mapState"),canvas=m.editorField("mapCanvas");o.put("selected",s==null?-1:m.call(s,"selected",new Class[]{}));o.put("undo",s==null?-1:m.call(s,"undoCount",new Class[]{}));o.put("viewport",canvas==null?JSONObject.NULL:Arrays.toString((double[])m.call(canvas,"viewport",new Class[]{})));final JSONArray texts=new JSONArray();m.runOnMainSync(()->{try{v.inspect(m.activeDialogRoot(),texts);}catch(Exception e){throw new RuntimeException(e);}});o.put("texts",texts);m.capture("mvisual-geometry-close-"+tag);v.emit("GEOMETRY_CLOSE_VISUAL "+o);}
 void launch(long id)throws Exception{v.finish();m.activity=m.startActivitySync(new Intent().setClassName(m.getTargetContext().getPackageName(),"org.rabochaya.projects.GeometryEditorActivity").putExtra("project",id).putExtra("feature","point").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));m.geometryReady();}
 void closed()throws Exception{long end=System.currentTimeMillis()+10000;while(!m.activity.isFinishing()&&!m.activity.isDestroyed()&&System.currentTimeMillis()<end){m.waitForIdleSync();Thread.sleep(100);}m.check(m.activity.isFinishing()||m.activity.isDestroyed(),"only explicit close action finishes Activity");}
 void run()throws Exception{m.installTileFixture();int requests=m.requests.get();Object store=m.storeClass.getConstructor(Context.class).newInstance(m.getTargetContext());long id=-1;try{id=g.fixture(store,false);Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));g.open(id,false);m.click("Редактировать на карте");m.mapEditorReady();m.dragVertex(1,14,8,false);String raw=m.editorText(),token=(String)m.editorField("expected"),process=(String)m.editorField("VERTEX_SESSION");double[] viewport=((double[])m.call(m.editorField("mapCanvas"),"viewport",new Class[]{})).clone();boolean all=true;
 prompt();m.click("Продолжить редактирование");m.check(!present()&&m.editorText().equals(raw)&&(Integer)m.call(m.vertexState(),"undoCount",new Class[]{})==1,"explicit Cancel keeps private raw and Undo");g.unchanged(store,id,xml,assets);snapshot("cancelled");
 for(int direction:new int[]{UiAutomation.ROTATION_FREEZE_90,UiAutomation.ROTATION_FREEZE_0}){String tag=direction==UiAutomation.ROTATION_FREEZE_90?"land":"return";prompt();snapshot("before-"+tag);Activity old=m.activity;c.rotate(direction);snapshot("after-"+tag);m.check(old!=m.activity&&old.isDestroyed()&&c.layout().getBoolean("interactiveThreshold"),"close actual destroyed/recreate and original80px map guard");boolean restored=present();all&=restored;m.check(!m.activity.isFinishing()&&(Long)m.editorField("project")==id&&"point".equals(m.editorField("featureId"))&&process.equals(m.editorField("VERTEX_SESSION"))&&g.key().equals("0")&&token.equals(m.editorField("expected"))&&m.editorText().equals(raw)&&(Integer)m.call(m.vertexState(),"selected",new Class[]{})==1&&(Integer)m.call(m.vertexState(),"undoCount",new Class[]{})==1,"rotation never closes/writes/rebinds original raw/key/selection/Undo/context");double[] current=(double[])m.call(m.editorField("mapCanvas"),"viewport",new Class[]{});for(int axis=0;axis<3;axis++)m.check(Math.abs(current[axis]-viewport[axis])<1e-9,"close rotation keeps original viewport");g.unchanged(store,id,xml,assets);v.emit("GEOMETRY_CLOSE_RECREATE direction="+tag+" oldDestroyed="+old.isDestroyed()+" restored="+restored);if(restored)m.click("Продолжить редактирование");}
 prompt();m.click("Сохранить черновик");closed();g.unchanged(store,id,xml,assets);launch(id);m.check(m.editorText().equals(raw)&&g.key().equals("0"),"explicit SaveDraft closes and next launch restores only private raw");m.click("Редактировать на карте");m.mapEditorReady();m.check(!(Boolean)m.call(m.vertexState(),"canUndo",new Class[]{}),"new launch has no prior configuration Undo history");snapshot("saved-draft-reopened");g.unchanged(store,id,xml,assets);
 m.dragVertex(1,10,6,false);prompt();m.click("Отменить ввод");closed();g.unchanged(store,id,xml,assets);launch(id);m.check(m.editorText().equals("20 10 30\n21 11 31\n22 12 32")&&g.key().equals("0"),"explicit discard removes private input without modifying original KML");snapshot("discarded-reopened");g.unchanged(store,id,xml,assets);v.emit("GEOMETRY_CLOSE_DRAFT_CANCEL_DISCARD PASS");m.check(m.requests.get()==requests,"close probe never transfers objects or coordinates");m.check(all,"dirty editor close confirmation survives both actual Activity recreations");
 }finally{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);if(id>0)m.call(store,"remove",new Class[]{long.class},id);m.call(store,"close",new Class[]{});}}
}
